try:
    print(int('x') / 0)
except ValueError:
    print('Conversion failed')
except ZeroDivisionError:
    print('Division failed')

def parse_count(value):
    try:
        return int(value)
    except (TypeError, ValueError):
        return None
print(parse_count('12'))
print(parse_count(None))

